/** Actual installed browser API, real transfer packet and rendered category windows. */
public final class NativeMachineJeiChecks {
 private static int stage,ticks,wait;private static boolean capture;private static int captured;
 private static void need(boolean v,String why){if(!v)throw new AssertionError("Native machine JEI stage="+stage+": "+why);}
 private static void next(int n){stage=n;wait=0;}
 public static void tick(ClientTickEvent.Post e){if(!NativeMachineJeiFixture.enabled())return;var m=Minecraft.getInstance();try{if(m.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen intro){intro.onClose();return;}if(stage==8&&m.level==null){System.out.println("[vandorlabs][machine-jei] client PASS pluginDiscovery/categories2/recipes2+3/catalysts/charged10000RF/actualBrowser/realTransfer");stage=9;m.stop();return;}if(m.player==null||m.level==null||m.gameMode==null)return;need(++ticks<1200&&++wait<400,"timeout screen="+m.screen);var runtime=NativeMachineJeiPlugin.runtime();if(runtime==null)return;var manager=runtime.getRecipeManager();
  if(stage==0){var infuser=manager.getRecipeCategory(NativeMachineJeiPlugin.INFUSING);var tower=manager.getRecipeCategory(NativeMachineJeiPlugin.SYNTHESIS);need(infuser!=null&&tower!=null,"plugin discovered both actual categories");var recipes=manager.createRecipeLookup(NativeMachineJeiPlugin.INFUSING).get().toList();var cores=manager.createRecipeLookup(NativeMachineJeiPlugin.SYNTHESIS).get().toList();need(recipes.size()==2&&cores.size()==3,"exact registered recipe counts2+3");need(recipes.stream().anyMatch(r->r.kind()==MachineRecipeDisplay.Kind.CHARGING&&NativeBatteryModule.energy(r.input())==0&&NativeBatteryModule.energy(r.output())==10000),"physical fully charged output");need(recipes.stream().anyMatch(r->r.kind()==MachineRecipeDisplay.Kind.INFUSING&&r.input().is(Items.IRON_INGOT)&&r.output().is(com.vandorlabs.neoforge.VandorLabsBootstrap.MATTER_INGOT.get())),"iron to Matter Ingot");var ids=new HashSet<String>();for(var core:cores)ids.add(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(core.output().getItem()).toString());need(ids.equals(Set.of("vandorlabs:synthesis_tower_core","vandorlabs:assembly_press_core","vandorlabs:enclosed_gantry_core")),"three exact Core recipes");need(manager.createRecipeCatalystLookup(NativeMachineJeiPlugin.INFUSING).getItemStack().anyMatch(s->s.is(NativeInfuserBindings.BLOCK.asItem())),"Infuser catalyst");need(manager.createRecipeCatalystLookup(NativeMachineJeiPlugin.SYNTHESIS).getItemStack().anyMatch(s->s.is(NativeBuilderBindings.CORES.get("synthesis_tower").asItem())),"Tower catalyst");next(1);return;}
  if(stage==1){if(m.gameMode.getPlayerMode()!=GameType.SURVIVAL||m.player.getInventory().selected!=0||!m.player.getMainHandItem().isEmpty()||m.player.position().distanceToSqr(.5,96,-2.5)>.01||!(m.level.getBlockEntity(NativeMachineJeiFixture.POS) instanceof NativeInfuserEntity))return;var target=new Vec3(.5,96.5,0).subtract(m.player.getEyePosition()).normalize();if(m.player.getLookAngle().dot(target)<.9999)return;m.gameMode.useItemOn(m.player,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(.5,96.5,0),Direction.NORTH,NativeMachineJeiFixture.POS,false));next(2);return;}
  if(stage==2){if(!(m.screen instanceof NativeInfuserScreen gui)||wait<10)return;var category=manager.getRecipeCategory(NativeMachineJeiPlugin.INFUSING);var recipe=manager.createRecipeLookup(NativeMachineJeiPlugin.INFUSING).get().filter(r->r.kind()==MachineRecipeDisplay.Kind.INFUSING).findFirst().orElseThrow();var handler=runtime.getRecipeTransferManager().getRecipeTransferHandler(gui.getMenu(),category).orElseThrow();var dummy=new NativeBuilderEntity(NativeMachineJeiFixture.POS,NativeBuilderBindings.CORES.get("synthesis_tower").defaultBlockState());dummy.setLevel(m.level);var towerMenu=new NativeBuilderMenu(NativeBuilderBindings.MENU,99,m.player.getInventory(),dummy);need(runtime.getRecipeTransferManager().getRecipeTransferHandler(towerMenu,manager.getRecipeCategory(NativeMachineJeiPlugin.SYNTHESIS)).isEmpty(),"Tower generic transfer absent");var layout=manager.createRecipeLayoutDrawable(category,recipe,runtime.getJeiHelpers().getFocusFactory().getEmptyFocusGroup()).orElseThrow();need(handler.transferRecipe(gui.getMenu(),recipe,layout.getRecipeSlotsView(),m.player,false,false)==null,"actual recipe transfer preflight");need(handler.transferRecipe(gui.getMenu(),recipe,layout.getRecipeSlotsView(),m.player,false,true)==null,"actual JEI transfer packet");next(3);return;}
  if(stage==3){if(!(m.screen instanceof NativeInfuserScreen gui)||!gui.getMenu().contents().getItem(0).is(Items.IRON_INGOT)||gui.getMenu().contents().getItem(1).getCount()!=7||!m.player.getInventory().getItem(9).isEmpty()||!m.player.getInventory().getItem(10).isEmpty())return;System.out.println("[vandorlabs][machine-jei] transfer PASS realSurvivalMenu/JEIpacket/iron1+redstone7");runtime.getRecipesGui().showTypes(List.of(NativeMachineJeiPlugin.INFUSING));next(4);return;}
  if(stage==4||stage==6){if(wait<20)return;need(m.screen!=null&&m.screen.getClass().getName().startsWith("mezz.jei."),"actual browser open");capture=true;next(stage+1);return;}
  if(stage==5){if(capture)return;runtime.getRecipesGui().showTypes(List.of(NativeMachineJeiPlugin.SYNTHESIS));next(6);return;}
  if(stage==7){if(capture)return;need(captured==2,"two actual browser captures");m.level.disconnect();m.disconnect();next(8);}
 }catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][machine-jei] FAIL "+failure);m.stop();}}
 public static void frame(RenderFrameEvent.Post e)throws Exception{if(!capture)return;var m=Minecraft.getInstance();if(m.screen==null)return;try(var image=net.minecraft.client.Screenshot.takeScreenshot(m.getMainRenderTarget())){var colors=new HashSet<Integer>();for(int y=image.getHeight()/4;y<image.getHeight()*3/4;y+=2)for(int x=image.getWidth()/4;x<image.getWidth()*3/4;x+=2)colors.add(image.getPixelRGBA(x,y));need(colors.size()>64,"actual browser pixels contain authored textured recipes");image.writeToFile(m.gameDirectory.toPath().resolve(captured++==0?"machine-jei-infusing.png":"machine-jei-synthesis.png"));capture=false;}}
 private NativeMachineJeiChecks(){}
}
